// ============================================================
// SavedSearches — Saved Filter List (SA-014)
// ============================================================
// Collapsible panel showing user's saved search filters.
// Check/uncheck to combine filters, search to find them,
// bulk select/delete actions.
//
// Bridge: reads from legacy window.savedFilters during migration.
// ============================================================

import { useState, useCallback, useMemo } from 'react';

interface SavedSearchItem {
  id: string;
  name: string;
  color: string;
  checked: boolean;
  filterNum?: string;
  pillSummary?: Array<{ label: string; type: 'include' | 'exclude' | 'where' }>;
}

interface SavedSearchesProps {
  items: SavedSearchItem[];
  onToggle: (id: string) => void;
  onDelete: (ids: string[]) => void;
  onSelectAll: (checked: boolean) => void;
  collapsed?: boolean;
  onToggleCollapse?: () => void;
}

export function SavedSearches({
  items,
  onToggle,
  onDelete,
  onSelectAll,
  collapsed = false,
  onToggleCollapse,
}: SavedSearchesProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedForDelete, setSelectedForDelete] = useState<Set<string>>(new Set());

  const checkedCount = items.filter(i => i.checked).length;

  const filteredItems = useMemo(() => {
    if (!searchQuery.trim()) return items;
    const q = searchQuery.toLowerCase();
    return items.filter(i => i.name.toLowerCase().includes(q));
  }, [items, searchQuery]);

  const _toggleDeleteSelect = useCallback((id: string) => {
    setSelectedForDelete(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }, []);

  const handleDeleteSelected = useCallback(() => {
    if (selectedForDelete.size === 0) return;
    onDelete(Array.from(selectedForDelete));
    setSelectedForDelete(new Set());
  }, [selectedForDelete, onDelete]);

  return (
    <div className="border border-border rounded-lg overflow-hidden">
      {/* Header */}
      <button
        type="button"
        className="flex items-center gap-2 w-full px-3 py-2.5 text-left text-[13px] font-semibold text-text-dim select-none hover:bg-bg-hover/50 transition-colors"
        onClick={onToggleCollapse}
      >
        <svg
          aria-hidden="true"
          viewBox="0 0 24 24"
          width={14}
          height={14}
          fill="none"
          stroke="currentColor"
          strokeWidth={2}
          className={`text-text-faint transition-transform ${collapsed ? '' : 'rotate-180'}`}
        >
          <polyline points="6 9 12 15 18 9" />
        </svg>
        <span className="text-[13px] font-semibold text-text-dim">Saved Searches</span>
        {checkedCount > 0 && (
          <span className="px-1.5 py-0.5 rounded-full text-[9px] font-bold bg-accent/10 text-accent">
            {checkedCount}
          </span>
        )}
      </button>

      {/* Body */}
      {!collapsed && items.length > 0 && (
        <div className="px-3 pb-3">
          {/* Controls row */}
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={checkedCount === items.length && items.length > 0}
                onChange={(e) => onSelectAll(e.target.checked)}
                className="cursor-pointer"
                title="Select / Deselect All"
              />
              <span className="text-[10px] text-text-faint">Select / Deselect All</span>
            </div>
            <div className="flex items-center gap-2">
              {selectedForDelete.size > 0 && (
                <button
                  type="button"
                  className="px-2.5 py-0.5 text-[10px] rounded bg-red-400/10 text-red-400 hover:bg-red-400/20 transition-colors"
                  onClick={handleDeleteSelected}
                >
                  Delete Selected
                </button>
              )}
              <input
                type="text"
                className="w-[120px] px-2 py-0.5 text-[10px] bg-bg-input border border-border rounded text-text placeholder:text-text-faint focus:border-accent focus:outline-none"
                placeholder="Search…"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          {/* Filter list */}
          <div className="space-y-0.5 max-h-[200px] overflow-y-auto">
            {filteredItems.map(item => (
              <label
                key={item.id}
                className="flex items-start gap-2 px-2 py-1.5 rounded hover:bg-bg-hover cursor-pointer group"
              >
                <input
                  type="checkbox"
                  checked={item.checked}
                  onChange={() => onToggle(item.id)}
                  className="cursor-pointer mt-0.5"
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5">
                    <span className="text-xs text-text-dim truncate">{item.name}</span>
                    {item.filterNum && (
                      <span
                        className="text-[9px] font-bold text-white px-1.5 py-0.5 rounded flex-shrink-0"
                        style={{ backgroundColor: item.color }}
                      >
                        {item.filterNum}
                      </span>
                    )}
                  </div>
                  {item.pillSummary && item.pillSummary.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1">
                      {item.pillSummary.slice(0, 8).map((pill, idx) => (
                        <span
                          key={idx}
                          className={`inline-block px-1.5 py-0.5 rounded-full text-[9px] font-semibold leading-none ${
                            pill.type === 'exclude'
                              ? 'bg-red-400/10 text-red-400'
                              : pill.type === 'where'
                              ? 'bg-orange-400/10 text-orange-400'
                              : 'bg-accent/10 text-accent'
                          }`}
                        >
                          {pill.label}
                        </span>
                      ))}
                      {item.pillSummary.length > 8 && (
                        <span className="text-[9px] text-text-faint">+{item.pillSummary.length - 8}</span>
                      )}
                    </div>
                  )}
                </div>
                <button
                  type="button"
                  className="opacity-0 group-hover:opacity-100 p-0.5 rounded hover:bg-red-400/20 text-text-faint hover:text-red-400 transition-all mt-0.5 flex-shrink-0"
                  title="Delete this search"
                  onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete([item.id]); }}
                >
                  <svg className="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                </button>
              </label>
            ))}
          </div>

          {filteredItems.length === 0 && (
            <p className="text-[10px] text-text-faint text-center py-2">
              {searchQuery ? 'No matching searches' : 'No saved searches yet'}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

export default SavedSearches;
